-- hrm.drop_expired_attendance_partitions: Drops the monthly partitions of hrm.attendance_events whose whole month lies before p_before (a date: the first day of the oldest month kept). Only partitions named attendance_events_pYYYY_MM are touched, never the default partition and never a month that has not completely ended before p_before, and a row is never deleted on its own: the append-only trigger stays. Returns the names dropped and the number of rows they held. Owned by the migration login and run with its rights, as meta.ensure_partitions.
create or replace function hrm.drop_expired_attendance_partitions(p_before date)
returns table (partition_name text, row_count bigint)
language plpgsql security definer
set search_path = pg_catalog, pg_temp
as $fn$
declare
    part record;
    month_start date;
    rows_held bigint;
begin
    if p_before is null then
        raise exception 'drop_expired_attendance_partitions: a date is required' using errcode = '22004';
    end if;
    for part in
        select c.relname as rel_name
        from pg_inherits i
        join pg_class c on c.oid = i.inhrelid
        join pg_class p on p.oid = i.inhparent
        join pg_namespace n on n.oid = p.relnamespace
        where n.nspname = 'hrm' and p.relname = 'attendance_events'
          and c.relname ~ '^attendance_events_p[0-9]{4}_[0-9]{2}$'
        order by c.relname
    loop
        month_start := to_date(substr(part.rel_name, length('attendance_events_p') + 1), 'YYYY_MM');
        if (month_start + interval '1 month')::date <= p_before then
            execute format('select count(*) from hrm.%I', part.rel_name) into rows_held;
            execute format('drop table hrm.%I', part.rel_name);
            partition_name := part.rel_name; row_count := rows_held;
            return next;
        end if;
    end loop;
end
$fn$;
revoke all on function hrm.drop_expired_attendance_partitions(date) from public;
grant execute on function hrm.drop_expired_attendance_partitions(date) to app_rw;
